set -a; . /root/daily-call-audit/.env; set +a; curl -sS -H "X-N8N-API-KEY: $N8N_API_KEY" "${N8N_BASE_URL}/api/v1/executions/19479?includeData=true" | python3 -c "
import sys, json
d = json.load(sys.stdin)
run = d['data']['resultData']['runData']['Drop Junk?'][0]
print('node:', run.get('source'))
print('outputs (branches):')
for i, branch in enumerate(run.get('data',{}).get('main',[])):
    print(f'  output[{i}] items={len(branch) if branch else 0}')
    if branch:
        item = branch[0].get('json', {})
        for k in ('call_id','duration_ms','transcript','call_status'):
            if k in item: print(f'    {k}={item[k]!r}'[:140])
"

